// intent: Exercises sort_by_key, resolve_indices, resolve_members, same_keys, and reserve_more with small and large object member sets.
#include <iostream>
#include <nlohmann/json.hpp>
#include <nlohmann/json_view.hpp>

int main() {
    try {
        // Create an ordered_json with duplicate keys and more than 16 members to trigger stable_sort and resolve_indices
        nlohmann::ordered_json j;
        for (int i = 0; i < 20; ++i) {
            j["key" + std::to_string(i)] = i;
        }
        j["key0"] = 99;
        nlohmann::ordered_json j2 = j;
        bool eq = (j == j2);
        std::cout << "Ordered json equal: " << (eq ? "true" : "false") << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << std::endl;
    }
    return 0;
}
